"""All-horse profiles with historical candidates kept separate from confirmation."""
import json
import numpy as np
import pandas as pd
from data import HERE,ROOT,IDS,period_data,save
def main():
 out=HERE/'report01';out.mkdir(exist_ok=False);a=pd.read_csv(HERE/'input01/starts.csv',dtype={c:str for c in IDS},low_memory=False);v=a[a.gap_group.notna()];rows=[]
 for period,g in period_data(v).items():
  for label,z in g.groupby('gap_group'):
   rows.append({'period':period,'group':label,'starts':len(z),'horses':z.horse_id.nunique(),'median_usual_days':z.typical5.median(),'mean_actual_gap':z.gap_days.mean(),'median_actual_gap':z.gap_days.median(),'mean_ratio':z.relative_interval.mean(),'median_ratio':z.relative_interval.median(),'mean_deviation_days':z.gap_deviation_days.mean(),'mean_rank':z.finish_position.mean(),'top3_pct':100*z.top3.mean(),'mean_rank_gain':z.rank_gain.mean()})
 pd.DataFrame(rows).to_csv(out/'personal_departure_summary.csv',index=False,encoding='utf-8-sig')
 profiles=pd.read_csv(HERE/'input01/horse_usual_profiles.csv',dtype={'horse_id':str});active=set(a[a.year.eq(2026)].horse_id);profiles['observed_in_2026']=profiles.horse_id.isin(active)
 historical=pd.read_csv(HERE/'personal01/profiles.csv',dtype={'horse_id':str});p=historical[historical.snapshot.eq('2026_updated')].drop(columns=['snapshot','horse_name']);profiles=profiles.merge(p,on='horse_id',suffixes=('_usual','_candidate'),validate='one_to_one')
 for folder,prefix in [('personal01','primary'),('small_sample01','small_sample')]:
  x=pd.read_csv(HERE/folder/'individual_validation.csv',dtype={'horse_id':str,'period':str});x=x[x.snapshot.eq('2026_updated')&x.period.eq('2026')].drop(columns=['snapshot','period','horse_name','preferred_gap_group']);x=x.rename(columns={c:prefix+'_'+c for c in x if c!='horse_id'});profiles=profiles.merge(x,on='horse_id',how='left',validate='one_to_one')
 profiles['confirmed_optimum']=False;profiles['interpretation']='historical_candidate_or_insufficient_support_no_confirmed_optimum'
 assert len(profiles)==2813 and profiles.horse_id.nunique()==2813
 profiles.to_csv(out/'all_horse_cycle_profiles.csv',index=False,encoding='utf-8-sig');profiles[profiles.observed_in_2026].to_csv(out/'horses_observed_2026_profiles.csv',index=False,encoding='utf-8-sig')
 # Named examples chosen for observed sample size, plus a positive but unconfirmed case.
 ex=profiles[profiles.horse_id.isin(['3102840','3103920','3101890'])];ex.to_csv(out/'descriptive_examples.csv',index=False,encoding='utf-8-sig');assert len(ex)==3
 H=a[a.H1_time.notna()];assert np.allclose(H.H1_time_adv,H.H1_time-H.relative_time)
 audit=json.loads((ROOT/'jeju/research/20261009_jockey_effects_v1/forecast01/fit_audit.json').read_text())
 for r in audit:assert r['train_last']<=r['cutoff']<str(r['year'])+'-01-01'
 main=pd.read_csv(HERE/'analysis01/effects.csv',dtype={'distance':str,'period':str});rep=pd.read_csv(HERE/'analysis01/repeat_checks.csv');person=pd.read_csv(HERE/'personal01/individual_validation.csv',dtype={'period':str});small=pd.read_csv(HERE/'small_sample01/individual_validation.csv',dtype={'period':str});pool=pd.read_csv(HERE/'personal01/pooled_validation.csv',dtype={'period':str});usual=profiles[profiles.observed_in_2026&profiles.usual_interval_days.notna()]
 d={'status':'personal_interval_departures_and_past_only_candidates_completed_no_confirmed_individual_optimum','period_start':'2017-01-13','period_end':'2026-09-19','partial_2026':True,'cohort_starts':len(a),'personal_baseline_starts':len(v),'personal_baseline_horses':v.horse_id.nunique(),'unknown_previous_interval':int(a.gap_days.isna().sum()),'known_gap_insufficient_usual_history':int((a.gap_days.notna()&a.gap_group.isna()).sum()),'personal_2024_2025_starts':10843,'personal_2026_starts':3938,'usual_history':'T-2 last5 completed intervals within730days, minimum3','relative_short_threshold':.75,'usual_upper_ratio':1.25,'very_long_threshold':2.,'absolute_interval_conditioned_primary':True,'pooled_primary_BH_tests':int((main.variant.eq('primary')&main.distance.eq('pooled')&main.support).sum()),'distance_primary_BH_tests':int((main.variant.eq('primary')&main.distance.ne('pooled')&main.support).sum()),'relative_departure_recent_repeated_supported':int(rep.repeated_supported.sum()),'historical_candidate_horses_2024':532,'historical_candidate_horses_2026_updated':708,'updated_candidates_observed_2026':int(((profiles.status_candidate=='historical_candidate_only')&profiles.observed_in_2026).sum()),'primary_individual_fitted_2024_2025':int((person.snapshot.eq('2024_fixed')&person.period.eq('2024_2025')&person.status.eq('fitted')).sum()),'primary_individual_fitted_2026':int((person.period.eq('2026')&person.status.eq('fitted')).sum()),'primary_individual_positive_supported':int(person.positive_supported.sum()),'exploratory_small_sample_fitted':int(small.status.eq('fitted').sum()),'exploratory_small_sample_positive_supported':int(small.exploratory_positive_supported.sum()),'confirmed_individual_optimum':False,'fixed_candidate_pooled_recent_repeated':bool(pool.positive_supported.all()),'horses_observed_2026_with_current_usual_baseline':len(usual),'current_usual_p25':usual.usual_interval_days.quantile(.25),'current_usual_median':usual.usual_interval_days.median(),'current_usual_p75':usual.usual_interval_days.quantile(.75),'fixed_correction_adopted':False,'new_predictive_gain_tested':False,'operationally_applied':False,'database_opened':False,'existing_research_pauses_preserved':True}
 save(HERE/'decision.json',d);save(out/'verification.json',{'status':'passed','all_horse_profiles':len(profiles),'named_examples':len(ex),'H1_advantage_sign_identity_checked':len(H),'annual_frozen_H1_cutoffs_verified':True,'no_confirmed_optimum_label':True,'all_counts_and_effect_table_joins_checked':True,'candidate_profiles_include_inactive_horses_explicitly':True});print(json.dumps(d,ensure_ascii=False),flush=True)
if __name__=='__main__':main()
